WITH TrackDuration AS (
    -- convert milliseconds to minutes and classify each track
    SELECT
        TrackId,
        Milliseconds / 60000.0 AS Minutes,
        CASE
            WHEN Milliseconds < 180000            THEN 'Short'      -- < 3 minutes
            WHEN Milliseconds < 300000            THEN 'Medium'     -- 3 – <5 minutes
            ELSE                                     'Long'        -- ≥ 5 minutes
        END AS Category
    FROM Track
),
RevenuePerTrack AS (
    -- total revenue generated by each track
    SELECT
        TrackId,
        SUM(UnitPrice * Quantity) AS Revenue
    FROM InvoiceLine
    GROUP BY TrackId
),
TrackData AS (
    -- merge duration/classification with revenue (0 if never sold)
    SELECT
        td.Category,
        td.Minutes,
        COALESCE(r.Revenue, 0) AS Revenue
    FROM TrackDuration td
    LEFT JOIN RevenuePerTrack r ON td.TrackId = r.TrackId
)
SELECT
    Category,
    ROUND(MIN(Minutes), 4)  AS Min_Time_Minutes,
    ROUND(MAX(Minutes), 4)  AS Max_Time_Minutes,
    ROUND(SUM(Revenue), 4)  AS Total_Revenue
FROM TrackData
GROUP BY Category
ORDER BY Category;